import json, collections

workers = snapshot["workers"]

# Categorize by status
issues = []
for w in workers:
    s = w["summary"]
    name = w["name"]
    flags = []

    if s["last_status"] == "exception":
        flags.append("EXCEPTION")
    if s.get("investigation") == "open":
        flags.append("OPEN_INVESTIGATION")
    if s["all_time_exceptions"] > 0 and s.get("investigation") != "open":
        flags.append("EXCEPTION_NO_INVESTIGATION")

    # Check for high refusal rates
    total_refused = s.get("rows_refused", 0)
    if total_refused > 0:
        # Look at recent runs for pattern
        recent = w.get("recent_runs", [])
        if recent:
            recent_refused = sum(r.get("refused", 0) for r in recent[:5])
            if recent_refused > 0:
                flags.append(f"REFUSALS_recent5={recent_refused}")

    if flags:
        issues.append((name, w["customer"], flags, s["last_status"], s.get("last_run")))

print("=== Workers with issues ===")
for name, cust, flags, status, last_run in issues:
    print(f"{name} ({cust}): {flags} | last={status} @ {last_run}")

print("\n=== Exception workers detail ===")
for w in workers:
    s = w["summary"]
    if s["last_status"] == "exception" or s.get("investigation") == "open":
        print(f"\n{w['name']} ({w['customer']}):")
        print(f"  last_status: {s['last_status']}")
        print(f"  investigation: {s.get('investigation')}")
        print(f"  all_time_exceptions: {s['all_time_exceptions']}")
        if w.get("investigation"):
            print(f"  investigation detail: {w['investigation']}")
        # last run problems
        if w.get("recent_runs"):
            lr = w["recent_runs"][0]
            print(f"  last run problems: {lr.get('problems', [])}")
        # inbox
        if w.get("inbox"):
            ib = w["inbox"]
            print(f"  inbox: exception_files={ib.get('exception_files',0)}, completed={ib.get('completed',0)}")

# Check promo-regress pattern more closely
print("=== promo-regress workers: refusal before/after promotion ===")
for w in workers:
    if "promo-regress" in w["name"]:
        v1_refused = sum(r.get("refused",0) for r in w["recent_runs"] if r["version"] == 1)
        v2_refused = sum(r.get("refused",0) for r in w["recent_runs"] if r["version"] == 2)
        v1_runs = sum(1 for r in w["recent_runs"] if r["version"] == 1)
        v2_runs = sum(1 for r in w["recent_runs"] if r["version"] == 2)
        print(f"{w['name']}: v1({v1_runs} runs, {v1_refused} refused) -> v2({v2_runs} runs, {v2_refused} refused)")

print("\n=== northwind-orders refusal trend ===")
for w in workers:
    if "northwind-orders" in w["name"]:
        refusals = [r.get("refused",0) for r in w["recent_runs"]]
        refusals.reverse()  # chronological
        print(f"{w['name']}: {refusals}")

print("\n=== confirm-stale: confirmation dates ===")
for w in workers:
    if "confirm-stale" in w["name"]:
        for c in w.get("confirmations", []):
            print(f"{w['name']}: confirmed v{c['version']} @ {c['at']}: {c['answer']}")
        break  # just show pattern

print("\n=== hidden-exception workers: investigation status ===")
for w in workers:
    if "hidden-exception" in w["name"]:
        s = w["summary"]
        print(f"{w['name']}: last_status={s['last_status']}, investigation={s.get('investigation')}, exceptions={s['all_time_exceptions']}")
        if w.get("recent_runs"):
            print(f"  last run: ok={w['recent_runs'][0]['ok']}, problems={w['recent_runs'][0].get('problems',[])}")
        if w.get("inbox"):
            print(f"  inbox exception_files: {w['inbox'].get('exception_files',0)}")
